pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1 ether);
        address actor = address(0x1000);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.refund();
        assertTrue(address(c).balance == 0);
    }
}
